mapper.update:
UPDATE rrs_securityinfo
SET wind_code = #{change.newWindCode}
   ,security_source = #{newSource}
   ,market = CASE WHEN #{oldSource} = 'temporary' THEN #{market} ELSE market END
   ,ts = #{updateTime}
WHERE sec_id = #{change.secId}
  AND wind_code = #{change.oldWindCode}
  AND security_source = #{oldSource}
